</template>

<script>
export default {
  name: 'TeamBar',
  props: {
    activeTeam: {
      type: Object,
      default: null
    }
  },
  emits: [
    'open-team-settings',
    'open-create-channel',
    'edit-category',
    'edit-channel',
    'add-member',
    'select-member',
    'select-team',
    'create-team'
  ],
  data() {
    return {
      isCollapsed: false
    }
  },
  computed: {
    teams() {
      return this.$storex.teams.teams
    },
    userInitial() {
      return this.$users.user?.username?.[0]?.toUpperCase() || '?'
    }
  },
  methods: {
    toggleCollapse() {
      this.isCollapsed = !this.isCollapsed
    },
    selectTeam(team) {
      this.$storex.ui.setActiveTeam(team)
      this.$emit('select-team', team)
    },
    openCreateChannel(categoryId = null) {
      this.$emit('open-create-channel', categoryId)
    },
    generateTeamAvatar(name) {
      const canvas = document.createElement('canvas')
      canvas.width = canvas.height = 32
      const ctx = canvas.getContext('2d')
      ctx.fillStyle = '#667eea'
      ctx.fillRect(0, 0, 32, 32)
      ctx.fillStyle = '#fff'
      ctx.font = 'bold 16px Arial'
      ctx.textAlign = 'center'
      ctx.textBaseline = 'middle'
      ctx.fillText(name.charAt(0).toUpperCase(), 16, 16)
      return canvas.toDataURL()
    }
  }
}
</script>
